import{_ as e}from"./chunks/img.Dck1PxLc.js";import{_ as n,C as a,c as t,o as i,j as r,G as o,a0 as l,a as s}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Over Pétanque Academy","description":"","frontmatter":{},"headers":[],"relativePath":"nl/about.md","filePath":"nl/about.md"}');const h=n({name:"nl/about.md"},[["render",function(n,d,h,u,g,p){const m=a("AdBanner"),c=a("AdInArticle");return i(),t("div",null,[d[0]||(d[0]=r("h1",{id:"over-petanque-academy",tabindex:"-1"},[s("Over Pétanque Academy "),r("a",{class:"header-anchor",href:"#over-petanque-academy","aria-label":'Permalink to "Over Pétanque Academy"'},"​")],-1)),o(m),d[1]||(d[1]=l('<h2 id="een-passie-voor-petanque" tabindex="-1">Een passie voor pétanque <a class="header-anchor" href="#een-passie-voor-petanque" aria-label="Permalink to &quot;Een passie voor pétanque&quot;">​</a></h2><p>Welkom bij Pétanque Academy, waar een diepgewortelde passie voor pétanque al meer dan 45 jaar de drijvende kracht is. Mijn reis met deze sport is er een van toewijding, vaardigheid en onophoudelijk enthousiasme.</p><p>Pétanque is meer dan alleen een spel; het is een manier om contact te leggen, strategieën te bedenken en van het buitenleven te genieten, en ik heb het geluk gehad om de vele facetten ervan bijna een halve eeuw te mogen ervaren. Of het nu gaat om de precieze plaatsing van een boule of de kameraadschap op het veld, mijn toewijding aan pétanque is nog steeds even sterk.</p><p><img src="'+e+'" alt="Patrik Wiik with friends"></p><p><em>Het delen van deze passie met vrienden maakt pétanque echt bijzonder. De talloze uren die je op de baan doorbrengt, gevuld met gelach, vriendschappelijke competitie en gedeelde verhalen, smeden banden voor het leven.</em></p><hr><h2 id="mijn-missie" tabindex="-1">Mijn missie <a class="header-anchor" href="#mijn-missie" aria-label="Permalink to &quot;Mijn missie&quot;">​</a></h2><p>De missie van Pétanque Academy is om topspelers te helpen hun volledige potentieel te ontplooien door aandacht te besteden aan het mentale aspect – het vaak over het hoofd geziene element dat goede spelers onderscheidt van geweldige spelers.</p><p>Via deze site deel ik:</p><ul><li><strong>Mentale spelkaders</strong> ontwikkeld op basis van decennialange ervaring</li><li><strong>Praktische hulpmiddelen en sjablonen</strong> voor het stellen van doelen en training</li><li><strong>Workshopmethoden</strong> voor het opbouwen van psychologische veiligheid</li><li><strong>Op bewijs gebaseerde benaderingen</strong> voor prestaties onder druk</li></ul><p>Het gaat hier niet om technische coaching, maar om het creëren van een mentale basis waardoor je technische vaardigheden optimaal tot hun recht komen wanneer het er het meest toe doet.</p><hr><h2 id="waarom-ik-deze-website-heb-gemaakt" tabindex="-1">Waarom ik deze website heb gemaakt <a class="header-anchor" href="#waarom-ik-deze-website-heb-gemaakt" aria-label="Permalink to &quot;Waarom ik deze website heb gemaakt&quot;">​</a></h2><p>Na meer dan 45 jaar pétanque heb ik talloze getalenteerde spelers zien worstelen, niet met techniek, maar met:</p><ul><li><strong>Innerlijke criticus</strong> die het zelfvertrouwen ondermijnt na fouten</li><li><strong>Druk</strong> waardoor ze anders gaan spelen tijdens wedstrijden.</li><li><strong>Gebrek aan structuur</strong> in mentale training</li><li><strong>Isolatie</strong> in hun ontwikkelingstraject</li></ul><p>Deze site is opgericht om daar verandering in te brengen. Alle content hier is ontworpen om direct toepasbaar te zijn: sjablonen die je kunt kopiëren, frameworks die je vandaag nog kunt gebruiken en tools die werken in de echte concurrentie.</p><hr>',17)),o(c),d[2]||(d[2]=l('<p>Neem contact op</p><p>Ik hoor graag van u! Of u nu vragen hebt, uw ervaringen wilt delen of geïnteresseerd bent in workshops en trainingen, neem gerust contact op.</p><h3 id="contactgegevens" tabindex="-1">Contactgegevens <a class="header-anchor" href="#contactgegevens" aria-label="Permalink to &quot;Contactgegevens&quot;">​</a></h3><p><strong>E-mail:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="help-me-deze-site-te-verbeteren" tabindex="-1">Help me deze site te verbeteren <a class="header-anchor" href="#help-me-deze-site-te-verbeteren" aria-label="Permalink to &quot;Help me deze site te verbeteren&quot;">​</a></h2><p>Uw feedback is van onschatbare waarde! Deze website wordt voortdurend ontwikkeld op basis van de daadwerkelijke behoeften van topspelers.</p><p>Ik hoor graag van u over:</p><div class="tip custom-block"><p class="custom-block-title">Wat zou u het meest helpen?</p><ul><li><p><strong>Welke soorten content zou je graag vaker willen zien?</strong></p><ul><li>Meer mentale speltechnieken?</li><li>Meer praktische sjablonen?</li><li>Casestudies van topspelers?</li></ul></li><li><p><strong>Wat ontbreekt er op de site?</strong></p><ul><li>Onderwerpen die niet aan bod komen?</li><li>Hulpmiddelen waarvan je zou willen dat ze bestonden?</li><li>Kunt u de benodigde informatie niet vinden?</li></ul></li><li><p><strong>Wat werkt goed?</strong> Welke pagina&#39;s waren het meest nuttig? Welke hulpmiddelen heb je daadwerkelijk gebruikt? Wat maakte voor jou het grootste verschil?</p></li><li><p><strong>Hoe kan ik het verbeteren?</strong></p><ul><li>Verbeteringen in de navigatie?</li><li>Inhoudsorganisatie?</li><li>Meer voorbeelden?</li><li>Verschillende formaten?</li></ul></li></ul></div><h3 id="stuur-me-je-feedback" tabindex="-1">Stuur me je feedback <a class="header-anchor" href="#stuur-me-je-feedback" aria-label="Permalink to &quot;Stuur me je feedback&quot;">​</a></h3><p><strong>Stuur uw reactie per e-mail naar:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Suggesties voor de onderwerpregel:</strong></p><ul><li>&quot;Websitefeedback: [Uw onderwerp]&quot;</li><li>&quot;Contentverzoek: [Wat u nodig heeft]&quot;</li><li>&quot;Succesverhaal: [Hoe het geholpen heeft]&quot;</li><li>&quot;Suggestie: [Jouw idee]&quot;</li></ul><p><strong>Wat moet erin staan:</strong></p><ul><li>Je huidige niveau/ervaring</li><li>Waar je aan werkt</li><li>Specifieke feedback of verzoeken</li><li>Zijn er succesverhalen over het gebruik van de inhoud?</li></ul><hr><h2 id="wat-anderen-zeggen" tabindex="-1">Wat anderen zeggen <a class="header-anchor" href="#wat-anderen-zeggen" aria-label="Permalink to &quot;Wat anderen zeggen&quot;">​</a></h2><details class="details custom-block"><summary>Feedback van topspelers</summary><p><em>&quot;De inhoud over mentale training heeft mijn kijk op wedstrijden volledig veranderd. Alleen al het Inner Coach-raamwerk was de moeite waard om deze site te vinden.&quot;</em> — Regionaal kampioen, Frankrijk</p><p>&quot;Eindelijk iemand die begrijpt dat techniek niet het probleem is. De workshopmethodologie heeft onze club een compleet nieuwe manier van trainen gegeven.&quot; — Speler van het Zweedse nationale team</p><p><em>&quot;De sjabloon voor doelen en de dagboeksjabloon zijn precies wat ik nodig had. Simpel, praktisch en echt bruikbaar.&quot;</em> — Toernooispeler, Spanje</p></details><hr><h2 id="over-de-inhoud" tabindex="-1">Over de inhoud <a class="header-anchor" href="#over-de-inhoud" aria-label="Permalink to &quot;Over de inhoud&quot;">​</a></h2><p>Alle inhoud op deze site is:</p><ul><li><strong>Gratis en toegankelijk</strong> - Geen betaalmuren, geen verborgen inhoud</li><li><strong>Praktisch en direct toepasbaar</strong> - Sjablonen die u vandaag nog kunt gebruiken.</li><li><strong>Gebaseerd op bewijs</strong> - Gebaseerd op psychologisch onderzoek en meer dan 45 jaar ervaring</li><li><strong>Wordt continu bijgewerkt</strong> - Nieuwe inhoud wordt toegevoegd op basis van uw feedback</li></ul><hr><h2 id="privacy-en-cookies" tabindex="-1">Privacy en cookies <a class="header-anchor" href="#privacy-en-cookies" aria-label="Permalink to &quot;Privacy en cookies&quot;">​</a></h2><p>Deze website maakt gebruik van Google AdSense om de werking ervan te ondersteunen. Door deze website te gebruiken, stemt u in met het gebruik van cookies door Google voor advertentiepersonalisatie en -analyse.</p><p><strong>Wij respecteren uw privacy:</strong></p><ul><li>Er worden geen persoonlijke gegevens verzameld, behalve bij standaard analyses.</li><li>Geen e-maillijsten of spam</li><li>Contactgegevens worden alleen gebruikt om op uw berichten te reageren.</li></ul><hr><h2 id="verbinden-en-delen" tabindex="-1">Verbinden en delen <a class="header-anchor" href="#verbinden-en-delen" aria-label="Permalink to &quot;Verbinden en delen&quot;">​</a></h2><p>Als u deze inhoud waardevol vindt:</p><ul><li><strong>Deel het</strong> met je trainingspartners</li><li><strong>Beveel het aan</strong> bij je club</li><li><strong>Link ernaar</strong> vanuit je eigen bronnen</li><li><strong>Geef feedback</strong> om het te helpen verbeteren</li></ul><p>Samen kunnen we het mentale aspect van pétanque wereldwijd naar een hoger niveau tillen.</p><hr>',34)),o(m),d[3]||(d[3]=r("p",null,[r("strong",null,"Bedankt dat je deel uitmaakt van de Pétanque Academy!")],-1)),d[4]||(d[4]=r("p",null,[r("em",null,"— Patrik Wiik")],-1))])}]]);export{d as __pageData,h as default};
